import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    """
    Extract matches from all regular files in a directory.

    Parenthesized spans are returned without the surrounding parentheses;
    all other regex matches are returned as-is.
    """
    base_dir = Path(directory_path)
    if not base_dir.is_dir():
        return {}

    pattern = re.compile(regex_pattern)
    result = {}

    for file_path in sorted(base_dir.iterdir(), key=lambda p: p.name):
        if not file_path.is_file():
            continue

        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            result[file_path.name] = []
            continue

        matches = []
        for match in pattern.finditer(text):
            groups = match.groups()
            if groups:
                extracted = next((g for g in groups if g is not None), match.group(0))
                matches.append(extracted)
            else:
                token = match.group(0)
                if len(token) >= 2 and token.startswith("(") and token.endswith(")"):
                    matches.append(token[1:-1])
                else:
                    matches.append(token)

        result[file_path.name] = matches

    return result
